  function parseEquipmentCsv(text){
    return text.split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map(line=>{
      const parts=line.split(',').map(value=>value.trim());
      if(!/^[0-9]+[A-Z]$/.test(parts[0])) return null;
      const vibrationValues=[parts[1]||'',parts[2]||''].join(' ').match(/[0-9]+(?:\.[0-9]+)?/g)||[];
      const vibration=vibrationValues.length?Math.max(...vibrationValues.map(Number)):Number(parts[1]);
      const temperature=Number(parts[3]);
      const status=({'?뺤긽':'Normal','寃쎄퀬':'Warning','二쇱쓽':'Caution','?꾪뿕':'Critical'})[parts[4]]||parts[4];
      return Number.isFinite(vibration)&&Number.isFinite(temperature)?{id:parts[0],vibration,temperature,status}:null;
    }).filter(Boolean);
  }
